<script setup lang="ts">
import { computed,ref,watch } from 'vue';
import { realApi } from '../api/real';
const props=defineProps<{cycleId:string;editable:boolean}>();
const emit=defineEmits<{changed:[]}>();
const logs=ref<any[]>([]);
const friendly=(e:unknown)=>{const code=e instanceof Error?e.message:String(e);return ({AUTH_REQUIRED:'登录状态已失效，请刷新页面重新登录。',MANUAL_EDGE_INVALID:'请选择不同的评价人和被评价人。',MANUAL_REASON_REQUIRED:'请填写指定原因。',MANUAL_PARTICIPANT_INVALID:'成员不在本期有效参评名单中，请刷新名单。',ASSIGNMENT_EDGE_EXISTS:'该评价关系已存在。',ASSIGNMENT_CAPACITY_EXCEEDED:'评价任务数或被评价人数已达到上限。',ASSIGNMENT_LOCKED:'周期已开始，不能修改草稿关系。',CROSS_DEPARTMENT_REQUIRES_CYCLE_SCOPE:'跨部门指定需要本周期或全组织分配权限。',FORBIDDEN:'当前账号没有该范围的分配权限。',STATE_CONFLICT:'周期状态已变化，请刷新后重试。'} as Record<string,string>)[code]??'操作失败，请检查权限和周期状态后重试。';};
const participants=ref<any[]>([]),edges=ref<any[]>([]),reviewer=ref(''),target=ref(''),reason=ref(''),error=ref(''),busy=ref(false),reviewerDepartment=ref(''),targetDepartment=ref(''),message=ref('');
const departments=computed(()=>[...new Set(participants.value.map(p=>p.department_name).filter(Boolean))].sort());
watch(reviewerDepartment,()=>{reviewer.value='';error.value='';});
watch(targetDepartment,()=>{target.value='';error.value='';});
async function load(){try{const data=await realApi.getManualRelations(props.cycleId);participants.value=data.participants;edges.value=data.edges;logs.value=data.logs??[];}catch(e:unknown){error.value=friendly(e);}}
watch(()=>props.cycleId,()=>{reviewer.value='';target.value='';reviewerDepartment.value='';targetDepartment.value='';error.value='';void load();},{immediate:true});
const name=(id:string)=>participants.value.find(p=>p.user_id===id)?.display_name??null;
const nameOf=(id:string|null|undefined)=>id?(name(id)??'未记录'):'未记录';
const deptOf=(id:string|null|undefined)=>id?participants.value.find(p=>p.user_id===id)?.department_name??'未记录':'未记录';
const selectedReviewer=computed(()=>participants.value.find(p=>p.user_id===reviewer.value));
const selectedTarget=computed(()=>participants.value.find(p=>p.user_id===target.value));
/** 跨部门指定需要周期级授权，后端会再次校验；这里只做提醒。 */
const crossDepartment=computed(()=>!!selectedReviewer.value&&!!selectedTarget.value&&selectedReviewer.value.department_name!==selectedTarget.value.department_name);
const logsView=computed(()=>logs.value.map(l=>({...l,actionLabel:l.action==='assignment.manual.add'?'新增指定':'移除指定',actorLabel:l.actor_name??'未记录',pairLabel:l.reviewer_id||l.target_id?`${nameOf(l.reviewer_id)} → ${nameOf(l.target_id)}`:'未记录',reasonLabel:l.reason_text??'未记录原因'})));
async function save(remove=false,edge?:any){busy.value=true;error.value='';message.value='';try{const result:any=await realApi.setManualRelation(props.cycleId,edge?.reviewer_id??reviewer.value,edge?.target_id??target.value,remove,reason.value);reason.value='';message.value=remove?'已移除指定关系。':result?.cross_department?'已保存跨部门指定关系（已记入操作记录），可继续指定或在本页预览系统分配。':'已保存指定关系，可继续指定或在本页预览系统分配。';emit('changed');await load();}catch(e:unknown){error.value=friendly(e);}finally{busy.value=false;}}
</script>
<template><section class="card"><div class="section-heading"><div><h2>人工指定评价关系（选填）</h2><p>仅需指定特殊关系；其他关系由系统在预检时自动分配。仅显示授权范围内的人员。</p></div></div><p v-if="error" role="alert">{{ error }}</p><p v-if="message" role="status">{{message}}</p><div v-if="editable" class="form-grid"><div class="field"><label>评价人部门</label><select v-model="reviewerDepartment"><option value="">请选择部门</option><option v-for="d in departments" :key="d" :value="d">{{d}}</option></select></div><div class="field"><label>评价人</label><select v-model="reviewer" :disabled="!reviewerDepartment"><option value="">请选择人员</option><option v-for="p in participants.filter(p=>p.department_name===reviewerDepartment)" :key="p.user_id" :value="p.user_id">{{p.display_name}}</option></select></div><div class="field"><label>被评价人部门</label><select v-model="targetDepartment"><option value="">请选择部门</option><option v-for="d in departments" :key="d" :value="d">{{d}}</option></select></div><div class="field"><label>被评价人</label><select v-model="target" :disabled="!targetDepartment"><option value="">请选择人员</option><option v-for="p in participants.filter(p=>p.department_name===targetDepartment && p.user_id!==reviewer)" :key="p.user_id" :value="p.user_id">{{p.display_name}}</option></select></div><div class="field"><label>指定原因</label><input v-model.trim="reason" maxlength="500" placeholder="请输入指定原因"></div><p v-if="crossDepartment" class="hint">跨部门指定：会写入操作记录；只有持有本周期管理授权的账号可以保存，系统预检仍会复核。</p><button class="btn btn-primary" :disabled="busy||!reviewer||!target||reviewer===target||!reason" @click="save()">保存指定关系</button></div><div class="table-wrap"><h3>当前人工指定关系</h3><table class="table"><thead><tr><th>评价人</th><th>被评价人</th><th>指定原因</th><th>操作</th></tr></thead><tbody><tr v-for="edge in edges" :key="edge.id"><td>{{ name(edge.reviewer_id) }}</td><td>{{ name(edge.target_id) }}</td><td>{{ edge.reason||'历史记录未提供' }}</td><td><button v-if="editable" class="btn" :disabled="busy" @click="save(true,edge)">移除</button><span v-else>已锁定</span></td></tr></tbody></table><p v-if="!edges.length">暂无人工指定，系统将按规则自动分配。</p></div></section><div class="table-wrap"><h3>配置操作记录</h3><p class="hint">记录谁在何时新增或移除了指定关系；旧记录缺少的字段显示「未记录」，不做补造。</p><table class="table"><thead><tr><th>时间</th><th>操作人</th><th>操作</th><th>关系</th><th>原因</th></tr></thead><tbody><tr v-for="log in logsView" :key="log.id"><td>{{ log.created_at?new Date(log.created_at).toLocaleString():'未记录' }}</td><td>{{ log.actorLabel }}</td><td>{{ log.actionLabel }}<span v-if="log.cross_department"> · 跨部门</span></td><td>{{ log.pairLabel }}</td><td>{{ log.reasonLabel }}</td></tr></tbody></table><p v-if="!logsView.length">暂无操作记录。</p></div></template>
